// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount < type(uint256).max / 2);
        Reverter r = new Reverter();
        vm.deal(address(this), amount);
        vm.deal(address(c), amount);

        bool ok;
        // owner is address(this) (set at deployment), so this call is authorized.
        try c.sendMoney(address(r), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: sendMoney never reverts, even when the target rejects funds.
        assertTrue(ok);
    }
}

contract Reverter {
    bool private __entered;
    SimpleWallet public c;
    function setTarget(SimpleWallet _c) external { c = _c; }
    receive() external payable {
        if (!__entered) {
            __entered = true;
            c.depositsCount();
            revert();
        }
        revert();
    }
}
